input.addEventListener('input',()=>{page=0;apply()});topic.addEventListener('change',()=>{page=0;apply()});for(const button of app.querySelectorAll('[data-faq-topic]'))button.onclick=()=>{input.value='';topic.value=button.dataset.faqTopic;page=0;apply();app.querySelector('.topic-directory').open=false;app.querySelector('#finder-count').scrollIntoView({block:'start'});};app.querySelector('#finder-reset').onclick=()=>{input.value='';topic.value='All topics';page=0;apply();input.focus()};const focus=()=>{const count=app.querySelector('#finder-count');count.tabIndex=-1;count.focus();count.scrollIntoView({block:'start'})};app.querySelector('#finder-prev').onclick=()=>{page--;apply();focus()};app.querySelector('#finder-next').onclick=()=>{page++;apply();focus()};apply(false);document.title=`${records.length} POSH FAQs | The Cosmic Energizers`;
